import{_ as a,o as t,c as o,ae as r}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"Módulo de Importaciones","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/importaciones.md","filePath":"modulos/importaciones.md","lastUpdated":null}'),i={name:"modulos/importaciones.md"};function l(s,e,d,n,c,m){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="modulo-de-importaciones" tabindex="-1">Módulo de Importaciones <a class="header-anchor" href="#modulo-de-importaciones" aria-label="Permalink to &quot;Módulo de Importaciones&quot;">​</a></h1><h2 id="descripcion" tabindex="-1">Descripción <a class="header-anchor" href="#descripcion" aria-label="Permalink to &quot;Descripción&quot;">​</a></h2><p>Centro de importación homologado con drag &amp; drop. Organizado en dos secciones: <strong>Comprometidos (META)</strong> y <strong>Realizados (REAL)</strong>.</p><h2 id="importaciones-disponibles" tabindex="-1">Importaciones Disponibles <a class="header-anchor" href="#importaciones-disponibles" aria-label="Permalink to &quot;Importaciones Disponibles&quot;">​</a></h2><h3 id="comprometidos-meta" tabindex="-1">Comprometidos (META) <a class="header-anchor" href="#comprometidos-meta" aria-label="Permalink to &quot;Comprometidos (META)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Importación</th><th>Archivo</th><th>Procesamiento</th></tr></thead><tbody><tr><td><strong>Estado de Resultados</strong></td><td>Excel multi-hoja</td><td>Cada hoja = un almacén, filas = conceptos ER, columnas = meses</td></tr><tr><td><strong>Mermas y Quebrantos</strong></td><td>Excel por almacén</td><td>Calcula META = Ventas × tasa (merma + quebranto) por línea de producto</td></tr></tbody></table><h3 id="realizados-real" tabindex="-1">Realizados (REAL) <a class="header-anchor" href="#realizados-real" aria-label="Permalink to &quot;Realizados (REAL)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Importación</th><th>Archivo</th><th>Procesamiento</th></tr></thead><tbody><tr><td><strong>Ventas PAR/PE</strong></td><td>Excel detallado</td><td>Lee columnas de meses por almacén y línea de producto</td></tr><tr><td><strong>PDF Realizado</strong></td><td>PDF</td><td>Extrae TOTAL GTOS DISTRIBUCION y RESULTADO DIRECTO OPERACIÓN</td></tr><tr><td><strong>Surtimiento a Tiendas</strong></td><td>Excel (CONS 2026.xlsx)</td><td>Oportunidad y Eficiencia por trimestre, distribuye en 3 meses</td></tr><tr><td><strong>Mermas Realizadas</strong></td><td>Formulario manual</td><td>Monto trimestral distribuido en 3 meses</td></tr></tbody></table><h2 id="detalle-por-importador" tabindex="-1">Detalle por Importador <a class="header-anchor" href="#detalle-por-importador" aria-label="Permalink to &quot;Detalle por Importador&quot;">​</a></h2><h3 id="ersheetimport" tabindex="-1">ERSheetImport <a class="header-anchor" href="#ersheetimport" aria-label="Permalink to &quot;ERSheetImport&quot;">​</a></h3><ul><li>Ubicación: <code>app/Imports/ERSheetImport.php</code></li><li>Detecta almacén por nombre de hoja (ej. &quot;PT AYUTLA&quot; → AYUTLA MIXES)</li><li>Mapea conceptos por nombre normalizado (mayúsculas, sin espacios extra)</li><li>Upsert por lotes de 500 para rendimiento</li><li>Columnas: fila 12+, columna A-C = concepto, D-O = enero-diciembre</li></ul><h3 id="ventasdetalladasimport" tabindex="-1">VentasDetalladasImport <a class="header-anchor" href="#ventasdetalladasimport" aria-label="Permalink to &quot;VentasDetalladasImport&quot;">​</a></h3><ul><li>Ubicación: <code>app/Imports/VentasDetalladasImport.php</code></li><li>Detecta almacenes por nombre en filas (no por hoja)</li><li>Dos hojas: &quot;PAR&quot; (Abasto Rural) y &quot;ESP&quot; (Programa Especial)</li><li>Crea líneas de producto automáticamente si no existen</li><li>Columnas de meses: enero=3, febrero=4, ... diciembre=17</li></ul><h3 id="surtimientotiendasimport" tabindex="-1">SurtimientoTiendasImport <a class="header-anchor" href="#surtimientotiendasimport" aria-label="Permalink to &quot;SurtimientoTiendasImport&quot;">​</a></h3><ul><li>Ubicación: <code>app/Imports/SurtimientoTiendasImport.php</code></li><li>Lee archivo &quot;CONS 2026.xlsx&quot; con estructura fija</li><li>Columnas: A=almacén, B=OportunidadQ1, C=EficienciaQ1, ... I=EficienciaQ4</li><li>Distribuye valor trimestral / 3 entre los meses del trimestre</li><li><strong>Sin redondeo</strong>: almacena precisión completa (ej. 11.50/3 = 3.8333...)</li><li>Mapeo de nombres normalizados (AYUTLA MIXE → AYUTLA MIXES, etc.)</li></ul><h3 id="mermasquebrantosimport" tabindex="-1">MermasQuebrantosImport <a class="header-anchor" href="#mermasquebrantosimport" aria-label="Permalink to &quot;MermasQuebrantosImport&quot;">​</a></h3><ul><li>Ubicación: <code>app/Imports/MermasQuebrantosImport.php</code></li><li>Mapeo de hojas: &quot;PT AYUTLA&quot; → AYUTLA MIXES, etc.</li><li>Lee filas 15-22 (PROGRAMA ABASTO RURAL) con tasas de <code>config/mermas.php</code></li><li>Columnas de ventas $: col E(4)=ENERO, G(6)=FEBRERO, ..., AA(26)=DICIEMBRE</li><li>Guarda como META</li></ul><h3 id="pdferextractorservice" tabindex="-1">PDFERExtractorService <a class="header-anchor" href="#pdferextractorservice" aria-label="Permalink to &quot;PDFERExtractorService&quot;">​</a></h3><ul><li>Ubicación: <code>app/Domain/Services/PDFERExtractorService.php</code></li><li>Detecta mes por nombre en el texto del PDF</li><li>Dos bloques de tiendas (9 + 4)</li><li>Regex: <code>/-?\\d{1,3}(?:,\\d{3})*(?:\\.\\d{2})?/</code></li><li>Escala ×1000 (el PDF muestra valores en miles)</li></ul>',19)])])}const h=a(i,[["render",l]]);export{u as __pageData,h as default};
